Add-Type -AssemblyName System.Drawing

$path = 'C:\Users\JHOSEP\OneDrive\Desktop\Polleria_SaukoChiken\assets\images\icono-logo.jpeg'
$bmp = New-Object System.Drawing.Bitmap($path)
Write-Output ("Size: {0}x{1} PixelFormat={2}" -f $bmp.Width, $bmp.Height, $bmp.PixelFormat)

$rect = New-Object System.Drawing.Rectangle(0, 0, $bmp.Width, $bmp.Height)
$data = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$bytes = New-Object byte[] ($data.Stride * $bmp.Height)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)
$bmp.UnlockBits($data)
$bmp.Dispose()

$stride = $data.Stride
$w = $rect.Width
$h = $rect.Height

# Threshold: pixel considered "content" if noticeably darker/more saturated than white
function IsContent($r, $g, $b) {
  return -not ($r -gt 238 -and $g -gt 238 -and $b -gt 238)
}

$minX = $w; $maxX = -1; $minY = $h; $maxY = -1
for ($y = 0; $y -lt $h; $y++) {
  $rowStart = $y * $stride
  for ($x = 0; $x -lt $w; $x++) {
    $i = $rowStart + $x * 4
    $b = $bytes[$i]; $g = $bytes[$i + 1]; $r = $bytes[$i + 2]
    if (IsContent $r $g $b) {
      if ($x -lt $minX) { $minX = $x }
      if ($x -gt $maxX) { $maxX = $x }
      if ($y -lt $minY) { $minY = $y }
      if ($y -gt $maxY) { $maxY = $y }
    }
  }
}
Write-Output ("Full content bbox: X {0}..{1} (w={2})  Y {3}..{4} (h={5})" -f $minX, $maxX, ($maxX - $minX + 1), $minY, $maxY, ($maxY - $minY + 1))

# Column profile to find the gap between emblem and wordmark
Write-Output "--- column occupancy (x : count) every 20px, within full bbox ---"
for ($x = $minX; $x -le $maxX; $x += 20) {
  $cnt = 0
  for ($y = $minY; $y -le $maxY; $y += 2) {
    $i = $y * $stride + $x * 4
    if (IsContent $bytes[$i + 2] $bytes[$i + 1] $bytes[$i]) { $cnt++ }
  }
  Write-Output ("x={0} {1}" -f $x, ('#' * [Math]::Min($cnt, 40)))
}

