# Wood = brown/orange: R notably > B, not too bright-white
function IsWood($r, $g, $b) {
  if ($r -lt 110) { return $false }
  if ($b -gt 150) { return $false }
  if (($r - $b) -lt 55) { return $false }
  return $true
}

$minX = 1024; $maxX = -1; $minY = 1024; $maxY = -1
for ($y = 300; $y -lt 800; $y++) {
  $rowStart = $y * $stride
  for ($x = 0; $x -lt 560; $x++) {
    $i = $rowStart + $x * 4
    if (IsWood $bytes[$i + 2] $bytes[$i + 1] $bytes[$i]) {
      if ($x -lt $minX) { $minX = $x }
      if ($x -gt $maxX) { $maxX = $x }
      if ($y -lt $minY) { $minY = $y }
      if ($y -gt $maxY) { $maxY = $y }
    }
  }
}
Write-Output ("Wood bbox (left 560px): X {0}..{1} (w={2})  Y {3}..{4} (h={5})" -f $minX, $maxX, ($maxX - $minX + 1), $minY, $maxY, ($maxY - $minY + 1))

# per-column top of wood to confirm circle shape
Write-Output "--- wood top/bottom per column (step 20) ---"
for ($x = $minX; $x -le $maxX; $x += 20) {
  $t = -1; $bt = -1
  for ($y = 300; $y -lt 800; $y++) {
    $i = $y * $stride + $x * 4
    if (IsWood $bytes[$i + 2] $bytes[$i + 1] $bytes[$i]) {
      if ($t -lt 0) { $t = $y }
      $bt = $y
    }
  }
  Write-Output ("x={0} top={1} bottom={2}" -f $x, $t, $bt)
}

