Add-Type -AssemblyName System.Drawing

$src = 'C:\Users\JHOSEP\OneDrive\Desktop\Polleria_SaukoChiken\assets\images\icono-logo.jpeg'
$outDir = 'C:\Users\JHOSEP\AppData\Local\Temp\opencode\preview'
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

$bx = 20; $by = 359; $bw = 964; $bh = 367

$orig = [System.Drawing.Bitmap]::new($src)
$crop = [System.Drawing.Bitmap]::new($bw, $bh, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$g = [System.Drawing.Graphics]::FromImage($crop)
$g.DrawImage($orig, [System.Drawing.Rectangle]::new(0, 0, $bw, $bh), [System.Drawing.Rectangle]::new($bx, $by, $bw, $bh), [System.Drawing.GraphicsUnit]::Pixel)
$g.Dispose()
$orig.Dispose()

$rect = [System.Drawing.Rectangle]::new(0, 0, $bw, $bh)
$data = $crop.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadWrite, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
$stride = $data.Stride
$bytes = [byte[]]::new($stride * $bh)
[System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $bytes, 0, $bytes.Length)

$bg = [System.Collections.Generic.HashSet[int]]::new()
$stack = [System.Collections.Generic.Stack[int]]::new()

$lastX = $bw - 1
$lastY = $bh - 1

for ($x = 0; $x -lt $bw; $x++) {
  foreach ($y in [int[]]@(0, $lastY)) {
    $i = $y * $stride + $x * 4
    if ($bytes[$i] -ge 230 -and $bytes[$i + 1] -ge 230 -and $bytes[$i + 2] -ge 230) {
      $k = $y * $bw + $x
      if ($bg.Add($k)) { $stack.Push($k) }
    }
  }
}
for ($y = 0; $y -lt $bh; $y++) {
  foreach ($x in [int[]]@(0, $lastX)) {
    $i = $y * $stride + $x * 4
    if ($bytes[$i] -ge 230 -and $bytes[$i + 1] -ge 230 -and $bytes[$i + 2] -ge 230) {
      $k = $y * $bw + $x
      if ($bg.Add($k)) { $stack.Push($k) }
    }
  }
}

while ($stack.Count -gt 0) {
  $k = $stack.Pop()
  $x = $k % $bw
  $y = [int][Math]::Floor($k / $bw)
  $nb = @()
  if ($x -gt 0)     { $nb += ,@($x - 1, $y) }
  if ($x -lt $lastX) { $nb += ,@($x + 1, $y) }
  if ($y -gt 0)     { $nb += ,@($x, $y - 1) }
  if ($y -lt $lastY) { $nb += ,@($x, $y + 1) }
  foreach ($n in $nb) {
    $nx = $n[0]; $ny = $n[1]
    $i = $ny * $stride + $nx * 4
    if ($bytes[$i] -ge 230 -and $bytes[$i + 1] -ge 230 -and $bytes[$i + 2] -ge 230) {
      $kk = $ny * $bw + $nx
      if ($bg.Add($kk)) { $stack.Push($kk) }
    }
  }
}
Write-Output ("bg pixels: {0} / {1}" -f $bg.Count, ($bw * $bh))

foreach ($k in $bg) {
  $x = $k % $bw
  $y = [int][Math]::Floor($k / $bw)
  $i = $y * $stride + $x * 4
  $mn = [Math]::Min($bytes[$i], [Math]::Min($bytes[$i + 1], $bytes[$i + 2]))
  $a = 255 - $mn
  if ($a -lt 0) { $a = 0 }
  $bytes[$i + 3] = [byte]$a
  if ($a -lt 250) { $bytes[$i] = 255; $bytes[$i + 1] = 255; $bytes[$i + 2] = 255 }
}

[System.Runtime.InteropServices.Marshal]::Copy($bytes, 0, $data.Scan0, $bytes.Length)
$crop.UnlockBits($data)

$lockupFile = Join-Path $outDir 'logo-lockup.png'
$crop.Save($lockupFile, [System.Drawing.Imaging.ImageFormat]::Png)
$crop.Dispose()
Write-Output ("saved {0}" -f $lockupFile)

input.newString:
.brand-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--primary-red) 0%, var(--primary-orange) 50%, var(--primary-gold) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 1.35rem;
  box-shadow: 0 0 15px rgba(216, 30, 5, 0.5);
  flex-shrink: 0;
}

/* Variante con el icono-logo oficial de la marca (assets/images/logo-icono.png) */
.brand-icon--logo {
  background: none;
  box-shadow: none;
  border-radius: 50%;
  overflow: hidden;
}

.brand-icon--logo img {
  width: 44px;
  height: 44px;
  object-fit: cover;
  border-radius: 50%;
  display: block;
}

/* Lockup horizontal completo del logo (assets/images/logo-saukos.png) */
.brand-lockup-img {
  height: 46px;
  width: auto;
  display: block;
}

.footer-brand .brand-lockup-img {
  height: 58px;
}

