input.newString:
/* NAVBAR RESPONSIVE
   El navbar tiene 10 enlaces, así que por debajo de ~1500px hay que ir
   comprimiendo la marca y los enlaces para que nada se desborde. */
@media (max-width: 1500px) {
  :root {
    --navbar-h: 84px;
    --brand-icon-size: 48px;
  }
  .nav-menu {
    gap: 1rem;
  }
  .nav-link {
    font-size: 0.85rem;
  }
  .brand-name {
    font-size: 1.4rem;
  }
  .brand-tagline {
    font-size: 0.55rem;
    letter-spacing: 1.2px;
  }
}

@media (max-width: 1200px) {
  :root {
    --navbar-h: 78px;
    --brand-icon-size: 44px;
  }
  .nav-menu {
    gap: 0.75rem;
  }
  .nav-link {
    font-size: 0.8rem;
  }
  /* El eslogan es decorativo: se oculta antes de que el menú se corte */
  .brand-tagline {
    display: none;
  }
  .cart-toggle-btn {
    width: 40px;
    height: 40px;
  }
}

@media (max-width: 1024px) {
  .top-bar {
    display: none;
  }
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

