input.newString:
.navbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--navbar-h);
  /* Contenedor más ancho para que logo + 10 enlaces + acciones quepan sin apretarse */
  max-width: 1900px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-shrink: 0;
  min-width: 0;
}

.brand-icon {
  width: var(--brand-icon-size);
  height: var(--brand-icon-size);
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--primary-red) 0%, var(--primary-orange) 50%, var(--primary-gold) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 1.7rem;
  box-shadow: 0 0 15px rgba(216, 30, 5, 0.5);
  flex-shrink: 0;
}

/* Variante con el icono-logo oficial de la marca (assets/images/logo-icono.png) */
.brand-icon--logo {
  background: none;
  box-shadow: none;
  border-radius: 50%;
  overflow: hidden;
}

.brand-icon--logo img {
  width: var(--brand-icon-size);
  height: var(--brand-icon-size);
  object-fit: contain;
  border-radius: 50%;
  display: block;
}

/* Lockup horizontal completo del logo (solo se usa en el footer) */
.brand-lockup-img {
  height: 62px;
  width: auto;
  display: block;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.brand-name {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
  color: var(--text-white);
  line-height: 1.05;
  white-space: nowrap;   /* "SAUKOS CHIKEN" nunca se parte en dos líneas */
}

.brand-name span {
  color: var(--primary-gold);
}

.brand-tagline {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 1.6px;
  color: var(--primary-orange-light);
  font-weight: 600;
  line-height: 1.2;
  margin-top: 3px;
  white-space: nowrap;   /* el eslogan tampoco se parte */
}

